#!/usr/bin/env node

const readline = require('readline');
const util = require('util');
const GoiasScriptCompiler = require('../src/compiler');
const pkg = require('../package.json');

/**
 * Roda de Prosa GoiásScript - Terminal Interativo Goiano
 * Terminal interativo para testar código GoiásScript
 */
class RodaDeProsa {
  constructor() {
    this.compiler = new GoiasScriptCompiler();
    this.história = [];
    this.variables = new Map();
    this.multilineBuffer = '';
    this.multilineMode = false;
    this.promptPrefix = 'goiás> ';
    this.multilinePrefix = '    ... ';

    // Configurar readline
    this.rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout,
      prompt: this.promptPrefix,
    });

    this.setupRodaDeProsa();
  }

  setupRodaDeProsa() {
    console.log(this.getMensagemBoasVindas());

    this.rl.prompt();

    this.rl.on('line', input => {
      this.handleInput(input.trim());
    });

    this.rl.on('close', () => {
      this.cabô_a_prosa();
    });

    // Configurar autocompletar
    this.rl.on('completer', this.autocomplete.bind(this));
  }

  getMensagemBoasVindas() {
    return `
 ██████╗  ██████╗ ██╗ █████╗ ███████╗    ██████╗ ███████╗██████╗ ██╗
██╔════╝ ██╔═══██╗██║██╔══██╗██╔════╝    ██╔══██╗██╔════╝██╔══██╗██║
██║  ███╗██║   ██║██║███████║███████╗    ██████╔╝█████╗  ██████╔╝██║
██║   ██║██║   ██║██║██╔══██║╚════██║    ██╔══██╗██╔════╝██╔═══╝ ██║
╚██████╔╝╚██████╔╝██║██║  ██║███████║    ██║  ██║███████╗██║     ███████╗
 ╚═════╝  ╚═════╝ ╚═╝╚═╝  ╚═╝╚══════╝    ╚═╝  ╚═╝╚══════╝╚═╝     ╚══════╝

🇧🇷 Roda de Prosa do GoiásScript v${pkg.version}!

💡 Comandos especiais: .desenrola, .mostra_os_trem, .zera_o_trem, .vaza

🎯 Pode começar a prosa, sô!
`;
  }

  async handleInput(input) {
    try {
      // Comandos especiais da Roda de Prosa
      if (input.startsWith('.')) {
        this.handleCommand(input);
        this.rl.prompt();
        return;
      }

      // Verificar se é linha vazia
      if (!input) {
        this.rl.prompt();
        return;
      }

      // Detectar modo multilinha
      if (this.isMultilineStart(input) || this.multilineMode) {
        this.handleMultiline(input);
        return;
      }

      // Executar código
      await this.executeCode(input);
    } catch (error) {
      console.error('❌ Ô rapaz! Deu ruim:', error.message);
    }

    this.rl.prompt();
  }

  isMultilineStart(input) {
    const multilineKeywords = [
      'faz_trem',
      'vai_na_frente_faz_trem',
      'se',
      'se_ocê_quiser',
      'enquanto_tiver',
      'vai_indo',
      'tenta_aí',
      'arruma_trem',
    ];

    return (
      multilineKeywords.some(keyword => input.includes(keyword)) &&
      input.includes('{') &&
      !input.includes('}')
    );
  }

  handleMultiline(input) {
    if (!this.multilineMode) {
      this.multilineMode = true;
      this.multilineBuffer = input;
      this.rl.setPrompt(this.multilinePrefix);
    } else {
      this.multilineBuffer += '\n' + input;
    }

    // Verificar se chegou ao final do bloco
    if (input.includes('}') || input === '') {
      this.executeCode(this.multilineBuffer);
      this.multilineMode = false;
      this.multilineBuffer = '';
      this.rl.setPrompt(this.promptPrefix);
    }

    this.rl.prompt();
  }

  async executeCode(code) {
    try {
      // Adicionar à história
      this.história.push(code);

      // Compilar e executar
      const result = this.compiler.compile(code, 'repl.gs');

      if (!result.success) {
        console.error('❌ Ô rapaz! Deu ruim na tradução:');
        if (result.errors) {
          result.errors.forEach(error => console.error(`  • ${error.message}`));
        }
        return;
      }

      // Mostrar warnings se houver
      if (result.warnings && result.warnings.length > 0) {
        console.warn('⚠️  Avisos:');
        result.warnings.forEach(warning => {
          console.warn(`  • ${warning.message}`);
        });
      }

      // Executar JavaScript gerado
      const evalResult = this.safeEval(result.javascript);

      // Mostrar resultado se não for undefined
      if (evalResult !== undefined) {
        console.log('💬', this.formatOutput(evalResult));
      }
    } catch (error) {
      console.error('❌ Ô rapaz! Deu ruim na execução:', error.message);
    }
  }

  safeEval(code) {
    try {
      // Criar contexto isolado para execução
      const context = {
        console: console,
        setTimeout: setTimeout,
        setInterval: setInterval,
        clearTimeout: clearTimeout,
        clearInterval: clearInterval,
        Date: Date,
        Math: Math,
        JSON: JSON,
        ...this.getGlobalVariables(),
      };

      // Executar código no contexto
      return eval(`(function() { ${code} })()`);
    } catch (error) {
      throw new Error(`Erro de execução: ${error.message}`);
    }
  }

  getGlobalVariables() {
    // Retornar variáveis que devem estar disponíveis globalmente
    const globals = {};

    // Adicionar métodos goianos
    globals.prosa = console.log;
    globals.prosa_erro = console.error;
    globals.prosa_aviso = console.warn;

    return globals;
  }

  formatOutput(value) {
    if (typeof value === 'object') {
      return util.inspect(value, {
        colors: true,
        depth: 3,
        compact: false,
      });
    }
    return value;
  }

  handleCommand(command) {
    const cmd = command.toLowerCase();

    switch (cmd) {
      case '.desenrola':
      case '.help':
        this.desenrola();
        break;

      case '.mostra_os_trem':
      case '.vars':
        this.mostra_os_trem();
        break;

      case '.lembra_aí':
      case '.history':
        this.lembra_aí();
        break;

      case '.limpa_o_terreiro':
      case '.clear':
        console.clear();
        console.log('🧹 Terreiro limpo, sô!');
        break;

      case '.zera_o_trem':
      case '.reset':
        this.zera_o_trem();
        break;

      case '.vaza':
      case '.cabô_a_prosa':
      case '.exit':
        this.cabô_a_prosa();
        break;

      case '.mostra_as_tralha':
      case '.packages':
        this.mostra_as_tralha();
        break;

      case '.methods':
        this.mostra_métodos_goianos();
        break;

      default:
        console.log(`❓ Não entendi esse comando: ${command}`);
        console.log('💡 Digite .desenrola para ver os comandos disponíveis');
    }
  }

  desenrola() {
    console.log(`
🇧🇷 Roda de Prosa GoiásScript - Comandos Disponíveis:

📋 Comandos da Prosa:
   .desenrola           - Desenrola esse trem (ajuda)
   .mostra_os_trem      - Mostra as variáveis na memória  
   .lembra_aí           - Lembra o que já conversamos (histórico)
   .limpa_o_terreiro    - Limpa a tela
   .zera_o_trem         - Zera tudo e começa de novo
   .vaza               - Vaza daqui (sair)
   .mostra_as_tralha   - Mostra os balaios instalados

🎯 Exemplos de código GoiásScript:

   Variáveis:
   uai nome é "João"
   trem idade é 25

   Funções:
   faz_trem saudar(nome) {
     faz_favor "Oi " mais nome
   }

   Arrays:
   uai numeros é [1, 2, 3]
   numeros.mapear(x => x vezes 2)

   Métodos goianos:
   "texto".gritando()
   GoianoMath.sorteia_um()

💡 Use Enter para executar. Para blocos multilinhas, termine com }
`);
  }

  mostra_os_trem() {
    console.log('📋 Variáveis na prosa:');

    if (this.variables.size === 0) {
      console.log('  Nenhuma variável ainda, sô');
    } else {
      this.variables.forEach((value, name) => {
        console.log(`  📦 ${name}: ${this.formatOutput(value)}`);
      });
    }
  }

  lembra_aí() {
    console.log('📚 Lembrando o que já conversamos:');

    if (this.história.length === 0) {
      console.log('  Ainda não conversamos nada');
    } else {
      this.história.forEach((cmd, index) => {
        console.log(`  ${index + 1}: ${cmd}`);
      });
    }
  }

  zera_o_trem() {
    this.história = [];
    this.variables.clear();
    this.multilineBuffer = '';
    this.multilineMode = false;

    console.log('🔄 Zerou tudo, sô!');
    console.log('✨ Histórico e variáveis limpinhos');
  }

  cabô_a_prosa() {
    console.log('\n🇧🇷 Tchau, sô! Volte sempre pra mais dois dedo de prosa!');
    console.log('✨ Obrigado por usar a Roda de Prosa GoiásScript!');
    process.exit(0);
  }

  mostra_as_tralha() {
    console.log('🧺 Balaios GoiásScript disponíveis:');
    console.log('');
    console.log('  Built-in:');
    console.log('  • goiano-utils - Utilitários essenciais');
    console.log('  • goiano-http - Cliente HTTP');
    console.log('  • goiano-db - Banco de dados');
    console.log('');
    console.log('💡 Use: gs-balaio pega <balaio> para pegar');
  }

  mostra_métodos_goianos() {
    console.log('🔧 Métodos Goianos Disponíveis:');
    console.log('');
    console.log('📝 Texto (String):');
    console.log('  • .gritando(), .cochichando(), .aparar()');
    console.log('  • .dividir(), .trocar(), .tem_no_meio(), .tamanho()');
    console.log('');
    console.log('📋 Lista (Array):');
    console.log('  • .mapear(), .filtrar(), .reduzir(), .pra_cada()');
    console.log('  • .bota_no_final(), .arranca_o_rabo(), .ordenar()');
    console.log('');
    console.log('🧮 GoianoMath:');
    console.log('  • .sorteia_um(), .arredondar(), .maior(), .menor()');
    console.log('  • .potencia(), .raiz_quadrada(), .absoluto()');
    console.log('');
    console.log('🌍 Globais:');
    console.log('  • prosa(), vira_numero(), depois_de()');
  }

  autocomplete(line) {
    const keywords = [
      'uai',
      'trem',
      'é',
      'faz_trem',
      'faz_favor',
      'se',
      'senão',
      'enquanto_tiver',
      'vai_indo',
      'para',
      'em',
      'de',
      'certeza',
      'de_jeito_nenhum',
      'nada',
      'prosa',
      'GoianoMath',
      'pega',
      'troca_ideia',
      'vai_na_frente',
      'espera_um_cadim',
    ];

    const methods = [
      'gritando',
      'cochichando',
      'dividir',
      'trocar',
      'tem_no_meio',
      'mapear',
      'filtrar',
      'reduzir',
      'bota_no_final',
      'sorteia_um',
      'arredondar',
    ];

    const allCompletions = [...keywords, ...methods];
    const hits = allCompletions.filter(c => c.startsWith(line));

    return [hits.length ? hits : allCompletions, line];
  }
}

// Iniciar Roda de Prosa
if (require.main === module) {
  new RodaDeProsa();
}

module.exports = RodaDeProsa;

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const { program } = require('commander');
const GoiasScriptCompiler = require('../src/compiler');
const pkg = require('../package.json');

// ASCII Art do GoiásScript
const logo = `
 ██████╗  ██████╗ ██╗ █████╗ ███████╗    ███████╗ ██████╗██████╗ ██╗██████╗ ████████╗
██╔════╝ ██╔═══██╗██║██╔══██╗██╔════╝    ██╔════╝██╔════╝██╔══██╗██║██╔══██╗╚══██╔══╝
██║  ███╗██║   ██║██║███████║███████╗    ███████╗██║     ██████╔╝██║██████╔╝   ██║   
██║   ██║██║   ██║██║██╔══██║╚════██║    ╚════██║██║     ██╔══██╗██║██╔═══╝    ██║   
╚██████╔╝╚██████╔╝██║██║  ██║███████║    ███████║╚██████╗██║  ██║██║██║        ██║   
 ╚═════╝  ╚═════╝ ╚═╝╚═╝  ╚═╝╚══════╝    ╚══════╝ ╚═════╝╚═╝  ╚═╝╚═╝╚═╝        ╚═╝   

🇧🇷 Linguagem de Programação Goiana v${pkg.version} — Goianês na Web
`;

class GoiasScriptCLI {
  constructor() {
    this.compiler = new GoiasScriptCompiler();
  }

  // Comando: traduz (compile)
  async traduz(filePath, options) {
    try {
      console.log('🔧 Traduzindo arquivo GoiásScript...\n');

      if (!fs.existsSync(filePath)) {
        console.error(`❌ Ô rapaz! Arquivo '${filePath}' não foi achado não!`);
        process.exit(1);
      }

      const code = fs.readFileSync(filePath, 'utf8');
      const result = this.compiler.compile(code, filePath);

      if (!result.success) {
        console.error('❌ Ô rapaz! Deu ruim na tradução!\n');
        if (result.errors && result.errors.length > 0) {
          console.error('🚨 Erros encontrados:');
          result.errors.forEach(error => console.error(`  • ${error.message}`));
        }
        process.exit(1);
      }

      // Mostrar warnings
      if (result.warnings && result.warnings.length > 0) {
        console.warn('⚠️  Warnings:');
        result.warnings.forEach(warning => {
          console.warn(`  • ${warning.message}`);
          if (warning.suggestion) {
            console.warn(`    💡 ${warning.suggestion}`);
          }
        });
        console.log();
      }

      // Mostrar informações de compilação
      if (options.verbose) {
        console.log('📊 Informações de Compilação:');
        console.log(`  • Tipos analisados: ${result.typeInfo?.typeCount || 0}`);
        console.log(`  • Módulos: ${result.moduleInfo?.hasModules ? 'Sim' : 'Não'}`);
        if (result.moduleInfo?.imports?.length > 0) {
          console.log(`  • Imports: ${result.moduleInfo.imports.length}`);
        }
        if (result.moduleInfo?.exports?.length > 0) {
          console.log(`  • Exports: ${result.moduleInfo.exports.length}`);
        }
        console.log();
      }

      // Salvar arquivo JavaScript
      const outputPath = options.output || filePath.replace('.gs', '.js');
      fs.writeFileSync(outputPath, result.javascript, 'utf8');

      console.log(`✅ Tradução concluída com sucesso!`);
      console.log(`📄 Arquivo gerado: ${outputPath}`);

      if (options.run) {
        console.log('\n🚀 Executando código compilado...\n');
        console.log('='.repeat(50));
        try {
          // Executar JavaScript gerado
          eval(result.javascript);
        } catch (execError) {
          console.error(`\n❌ Ô rapaz! Deu ruim na execução: ${execError.message}`);
        }
        console.log('='.repeat(50));
      }
    } catch (error) {
      console.error(`❌ Ô rapaz! Deu ruim aqui: ${error.message}`);
      process.exit(1);
    }
  }

  // Comando: bota_pra_moer (run)
  async bota_pra_moer(filePath) {
    console.log('🚀 Botando o código pra moer...\n');
    console.log('='.repeat(50));
    await this.traduz(filePath, { run: true, output: filePath.replace('.gs', '.temp.js') });

    // Limpar arquivo temporário
    const tempFile = filePath.replace('.gs', '.temp.js');
    if (fs.existsSync(tempFile)) {
      fs.unlinkSync(tempFile);
    }
    console.log('='.repeat(50));
  }

  // Comando: vê_se_tá_certo (check-types)
  async vê_se_tá_certo(filePath) {
    try {
      console.log('🔍 Vendo se o trem tá certo...\n');

      if (!fs.existsSync(filePath)) {
        console.error(`❌ Ô rapaz! Arquivo '${filePath}' não foi achado não!`);
        process.exit(1);
      }

      const code = fs.readFileSync(filePath, 'utf8');
      const result = this.compiler.compile(code, filePath);

      if (result.typeInfo) {
        console.log('📊 Análise de Tipos:');
        console.log(`  • Símbolos analisados: ${result.typeInfo.typeCount}`);

        if (result.typeInfo.symbols && Object.keys(result.typeInfo.symbols).length > 0) {
          console.log('\n📋 Tabela de Símbolos:');
          Object.entries(result.typeInfo.symbols).forEach(([name, info]) => {
            const typeIcon = this.getTypeIcon(info.type);
            console.log(`  ${typeIcon} ${name}: ${info.type} (${info.declarationType})`);
          });
        }
      }

      if (result.warnings && result.warnings.length > 0) {
        console.log('\n⚠️  Warnings de Tipos:');
        result.warnings.forEach(warning => {
          console.warn(`  • ${warning.message}`);
          if (warning.suggestion) {
            console.warn(`    💡 ${warning.suggestion}`);
          }
        });
      }

      if (result.errors && result.errors.length > 0) {
        console.log('\n🚨 Erros de Tipos:');
        result.errors.forEach(error => console.error(`  • ${error.message}`));
        process.exit(1);
      } else {
        console.log('\n✅ Tá tudo certo, sô! Nenhum problema encontrado!');
      }
    } catch (error) {
      console.error(`❌ Ô rapaz! Deu ruim aqui: ${error.message}`);
      process.exit(1);
    }
  }

  // Comando: arma_o_barraco (new)
  async arma_o_barraco(projectName, options = {}) {
    const template = options.template || 'basic';
    // path.resolve respeita caminho absoluto (/tmp/x) e relativo (meu-app);
    // path.join sempre prefixa cwd, quebra quando o user passa /tmp/...
    const projectPath = path.resolve(process.cwd(), projectName);

    try {
      if (fs.existsSync(projectPath)) {
        console.error(`❌ Ô rapaz! Já tem um projeto '${projectName}' aqui!`);
        process.exit(1);
      }

      console.log(`🚀 Armando o barraco do projeto: ${projectName} (template: ${template})\n`);

      // Criar estrutura do projeto
      fs.mkdirSync(projectPath);
      fs.mkdirSync(path.join(projectPath, 'src'));
      fs.mkdirSync(path.join(projectPath, 'docs'));

      // Estrutura adicional para templates
      if (template === 'web') {
        fs.mkdirSync(path.join(projectPath, 'public'));
      } else if (template === 'framework') {
        // Estrutura completa do framework
        fs.mkdirSync(path.join(projectPath, 'public'));
        fs.mkdirSync(path.join(projectPath, 'dist'));
        fs.mkdirSync(path.join(projectPath, 'scripts'));
        fs.mkdirSync(path.join(projectPath, 'src', 'components'), { recursive: true });
        fs.mkdirSync(path.join(projectPath, 'src', 'controllers'), { recursive: true });
        fs.mkdirSync(path.join(projectPath, 'src', 'services'), { recursive: true });
        fs.mkdirSync(path.join(projectPath, 'src', 'models'), { recursive: true });
        fs.mkdirSync(path.join(projectPath, 'src', 'config'), { recursive: true });
      }

      // Arquivo principal
      let mainFile;

      if (template === 'web') {
        // Usar template web externo
        const templatesPath = path.join(__dirname, '..', 'templates');
        const webTemplatePath = path.join(templatesPath, 'web-app.gs');

        if (fs.existsSync(webTemplatePath)) {
          mainFile = fs.readFileSync(webTemplatePath, 'utf-8');
          mainFile = mainFile.replace(/{{PROJECT_NAME}}/g, projectName);
        } else {
          // Fallback se não encontrar o template
          mainFile = `// ${projectName} - Aplicação Web GoiásScript v2.0
prosa("🚀 Carregando ${projectName}...");

trem appConfig é {
  nome: "${projectName}",
  versao: "1.0.0",
  tipo: "Aplicação Web GoiásScript"
};

prosta_serviço iniciarApp() {
  prosa("🎉 " mais appConfig.nome mais " iniciado!");
  prosa("📦 Versão: " mais appConfig.versao);
  prosa("⚡ Powered by GoiásScript v2.0");
}`;
        }
      } else {
        // Template básico
        mainFile = `// ${projectName} - GoiásScript v2.0
// Arquivo principal do projeto

prosa("=== Projeto ${projectName} ===");

trem mensagem é "Oi sô! Seu projeto GoiásScript tá funcionando!";
prosa(mensagem);

trem nome_projeto é "${projectName}";
prosa("Nome do projeto: " mais nome_projeto);

trem tecnologias é ["GoiásScript", "JavaScript", "Node.js"];
prosa("Tecnologias usadas:");

vai_indo (trem i é 0; i menor_que tecnologias.tamanho(); i = i mais 1) {
  prosa("• " mais tecnologias[i]);
}

trem numero_sorte = Math.floor(Math.random() * 100);
prosa("Número da sorte: " mais numero_sorte);

prosa("🎉 Projeto criado com sucesso!");
prosa("💡 Use: goiasscript vê_se_tá_certo para verificar tipos");
prosa("💡 Use: goiasscript traduz para gerar JavaScript");`;
      }

      const fileName = template === 'web' ? 'app.gs' : 'main.gs';
      fs.writeFileSync(path.join(projectPath, 'src', fileName), mainFile);

      // Arquivos específicos dos templates
      if (template === 'framework') {
        // Copiar todos os arquivos do template framework
        const templatesPath = path.join(__dirname, '..', 'templates');
        const frameworkTemplatePath = path.join(templatesPath, 'goias-web-framework');

        if (fs.existsSync(frameworkTemplatePath)) {
          this.copyTemplateDirectory(frameworkTemplatePath, projectPath, projectName);
        } else {
          console.log('⚠️  Template framework não encontrado, usando fallback...');
          // Criar arquivos básicos do framework
          this.createFrameworkFiles(projectPath, projectName);
        }
      } else if (template === 'web') {
        // Usar templates externos
        const templatesPath = path.join(__dirname, '..', 'templates');

        // Copiar template HTML
        const htmlTemplatePath = path.join(templatesPath, 'web-index.html');
        if (fs.existsSync(htmlTemplatePath)) {
          let htmlContent = fs.readFileSync(htmlTemplatePath, 'utf-8');
          htmlContent = htmlContent.replace(/{{PROJECT_NAME}}/g, projectName);
          fs.writeFileSync(path.join(projectPath, 'public', 'index.html'), htmlContent);
        }

        // Copiar servidor de desenvolvimento
        const devServerPath = path.join(templatesPath, 'dev-server.js');
        if (fs.existsSync(devServerPath)) {
