// Métodos MATEMÁTICOS — definidos em forma de atribuição
// para que GoianoMath.<metodo> apareça literalmente no runtime gerado
const GoianoMath = {};
GoianoMath.sorteio = () => Math.random();
GoianoMath.arredondar_baixo = (num) => Math.floor(num);
